def transform(grid):
    # The 1-filled rectangle is the board; colored dots outside it indicate
    # which orientation the board should have.
    ones = [(r, c) for r, row in enumerate(grid) for c, v in enumerate(row) if v == 1]
    r0, r1 = min(r for r, c in ones), max(r for r, c in ones)
    c0, c1 = min(c for r, c in ones), max(c for r, c in ones)
    board = [row[c0:c1 + 1] for row in grid[r0:r1 + 1]]
    h, w = len(board), len(board[0])

    inside = {}
    outside = {}
    for r, row in enumerate(grid):
        for c, v in enumerate(row):
            if v in (0, 1):
                continue
            if r0 <= r <= r1 and c0 <= c <= c1:
                inside.setdefault(v, []).append((r - r0, c - c0))
            else:
                outside.setdefault(v, []).append((r, c))

    guides = {
        color: pts[0] for color, pts in outside.items()
        if len(pts) == 1 and len(inside.get(color, [])) == 1
    }

    def corner(pos, height, width):
        r, c = pos
        return (0 if r <= (height - 1) / 2 else 1,
                0 if c <= (width - 1) / 2 else 1)

    if guides:
        gr = [p[0] for p in guides.values()]
        gc = [p[1] for p in guides.values()]
        guide_box = (min(gr), max(gr), min(gc), max(gc))

        def guide_corner(pos):
            r, c = pos
            return (0 if r <= (guide_box[0] + guide_box[1]) / 2 else 1,
                    0 if c <= (guide_box[2] + guide_box[3]) / 2 else 1)

        candidates = []
        for transposed in (False, True):
            for flip_r in (False, True):
                for flip_c in (False, True):
                    nh, nw = (w, h) if transposed else (h, w)

                    def map_pos(r, c):
                        if transposed:
                            r, c = c, r
                        if flip_r:
                            r = nh - 1 - r
                        if flip_c:
                            c = nw - 1 - c
                        return r, c

                    score = 0
                    for color, gpos in guides.items():
                        r, c = inside[color][0]
                        if corner(map_pos(r, c), nh, nw) != guide_corner(gpos):
                            score += 1

                    out = [[0] * nw for _ in range(nh)]
                    for r in range(h):
                        for c in range(w):
                            nr, nc = map_pos(r, c)
                            out[nr][nc] = board[r][c]
                    candidates.append((score, out))
        return min(candidates, key=lambda item: item[0])[1]

    return board
